import{_ as r,l as o,o as a,c as i,v as t,p as c,x as n,d as l,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"网络命名空间与 veth","description":"","frontmatter":{"title":"网络命名空间与 veth","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/netns-veth.md","filePath":"cs/netns-veth.md","lastUpdated":1789023840000}'),d={name:"cs/netns-veth.md"};function v(_,e,u,m,f,E){const s=o("Mermaid");return a(),i("div",null,[e[1]||(e[1]=t('<h1 id="网络命名空间与-veth" tabindex="-1">网络命名空间与 veth <a class="header-anchor" href="#网络命名空间与-veth" aria-label="Permalink to &quot;网络命名空间与 veth&quot;">​</a></h1><div class="epigraph"><p>每个 netns 有自己的设备列表、路由表、套接字与 conntrack；veth 是一对跨命名空间的虚拟网线，写一端从另一端 RX。</p><footer>—— 据 Linux namespaces(7)；内核 veth 驱动说明；cgroup/ns 主干课的网络维</footer></div><p><a href="/cs/netfilter-conntrack">上一课</a>的表是每命名空间一份。<a href="/cs/namespaces">namespaces</a> 主干已有隔离直觉。缺口是 <strong>网络维落地</strong>：lo、地址、以及容器常用的 veth pair。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>无 netns：所有进程共享一张网卡与端口空间。容器要独立 <code>listen :80</code>。<code>clone(CLONE_NEWNET)</code> 得到空栈（几乎只有 lo 需 up）。veth：创建 pair，一端移入容器 ns，一端留在宿主机或网桥。缺口：路由谁做 NAT（往往宿主机 POSTROUTING）；移动设备用 <code>setns</code>；与 <a href="/cs/device-nodes">设备节点</a> 不同——网卡不是 cdev 主次号那套，是 net_device。本课不把 CNI 插件写成 k8s 百科。</p><p><span class="marginnote">socket 属于创建它的 netns。fd 传出后仍绑原 ns，这是容器网络的细坑。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>宿主机：<code>ip link add veth0 type veth peer name veth1</code>，<code>ip link set veth1 netns pid</code>，两边配地址或桥。包：容器 TX veth1 → 宿主机 veth0 RX，再走 <a href="/cs/tx-path-qdisc">qdisc</a>/转发。对照 <a href="/cs/tmpfs">tmpfs</a>：一个隔离文件树，一个隔离协议栈。对照 SCSI：没有 LUN，只有 peer 指针。</p>',8)),(a(),c(p,null,{default:n(()=>[h(s,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E5%AE%B9%E5%99%A8%20netns%22%5D%20--%3E%20V1%5B%22veth1%22%5D%0A%20%20V1%20--%3E%20V0%5B%22veth0%20%E5%AE%BF%E4%B8%BB%E6%9C%BA%20ns%22%5D%0A%20%20V0%20--%3E%20BR%5B%22%E7%BD%91%E6%A1%A5%E6%88%96%E8%B7%AF%E7%94%B1%20NAT%22%5D%0A%20%20BR%20--%3E%20PHY%5B%22%E7%89%A9%E7%90%86%E7%BD%91%E5%8D%A1%22%5D%0A"})]),fallback:n(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>netns+veth 把「一台主机多份网络栈」收成原语，容器网络的其余都是桥、路由、策略的叠加。性能：每包多次协议栈与 skb 拷贝或转发。后课会有更快的旁路。不要写成 SDN 产品。与 <a href="/cs/cgroups">cgroup</a>：netns 不管 CPU，只管看见哪些设备。</p><p>iptables 要在正确的 ns 里下规则，否则「容器里关不掉宿主机端口」。</p><p>实现上：把物理网卡移进 ns 后，宿主默认路由可能断。veth 的 peer 指针跨 ns，拆 ns 要先把设备移回。socket 随创建 ns，SCM_RIGHTS 传出后仍绑旧栈。 读法上只引用<a href="/cs/netfilter-conntrack">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「网络栈 / 收发路径」课序里，对象是 <strong>网络命名空间与 veth</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 ipvlan/macvlan 的全部替代拓扑。不保证无线设备移 ns 的驱动支持。下一课把多端点收成二层：网桥与 tun/tap。</p><p>版本字段会变，课序钉的是机制对象「网络命名空间与 veth」，不是某一主线内核的结构体名。 后课默认：容器用 veth 接宿主机栈。软件网桥与用户态隧道设备，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>netns 复制设备、路由、套接字空间。</li><li>veth 是跨 ns 的成对虚线。</li><li>网桥与 tun/tap 是下一课。</li><li>出处：Linux <code>namespaces(7)</code>；veth；内核 netns 文档。</li></ul>',11))])}const k=r(d,[["render",v]]);export{A as __pageData,k as default};
